const animal = { legs: 4, sound: "..." };
const dog = Object.create(animal);
dog.sound = "woof";
const puppy = Object.create(dog);
puppy.age = 1;

console.log(Object.keys(puppy).join(","));
console.log("legs" in puppy, Object.hasOwn(puppy, "sound"));

const keys = [];
for (const key in puppy) {
  keys.push(key);
}

console.log(keys.join(","));
console.log("toString" in puppy, keys.includes("toString"));
